notes:
BEFORE (INSECURE - visitorId can be spoofed):
```typescript
export const getByVisitor = query({
  args: { visitorId: v.string() },  // ATTACKER CAN SEND ANY VALUE
  handler: async (ctx, { visitorId }) => {
    return ctx.db.query('wordProgress')
      .withIndex('by_visitor', q => q.eq('visitorId', visitorId))
      .collect();
  }
});
```

AFTER (SECURE - ctx.auth cannot be spoofed):
```typescript
import { getAuthUserId } from './authHelpers';

export const getByUser = query({
  args: {},  // NO USER ID ARGUMENT!
  handler: async (ctx) => {
    const userId = await getAuthUserId(ctx);
    if (!userId) return [];  // Not logged in = no data
    return ctx.db.query('wordProgress')
      .withIndex('by_user', q => q.eq('userId', userId))
      .collect();
  }
});
```

For mutations that REQUIRE auth, use requireAuth() which throws if not authenticated.
